"""Which adapter a port uses, read at each call: the environment variable, else the `env` of `.claude/settings.local.json`, then `settings.json`,
in the current git root, then the main checkout (a worktree has no local settings). The environment wins, as in Claude Code."""
import importlib
import json
import os
import pathlib
import subprocess

FILES = ("settings.local.json", "settings.json")


def git(*argv):
    try:
        run = subprocess.run(["git", *argv], capture_output=True, text=True)
    except OSError:
        return None
    return run.stdout.strip() if run.returncode == 0 and run.stdout.strip() else None


def roots():
    """The current git root, then the main checkout when it differs."""
    top, common = git("rev-parse", "--show-toplevel"), git("rev-parse", "--path-format=absolute", "--git-common-dir")
    found = [pathlib.Path(top)] if top else []
    if common and pathlib.Path(common).name == ".git" and pathlib.Path(common).parent not in found:
        found.append(pathlib.Path(common).parent)
    return found


def value(name, default):
    """The setting NAME: the environment, else the settings files' `env`, else DEFAULT."""
    if os.environ.get(name):
        return os.environ[name]
    for root in roots():
        for file in FILES:
            try:
                given = json.loads((root / ".claude" / file).read_text())["env"][name]
            except (OSError, ValueError, KeyError, TypeError):
                continue
            if isinstance(given, str) and given:
                return given
    return default


def kind(name):
    return value(name, "github")


def adapter(prefix, name):
    return importlib.import_module(f"{prefix}_{kind(name)}")
